'use strict';
const ICONS={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',back:'<path d="m14 6-6 6 6 6"/>',arrow:'<path d="m9 6 6 6-6 6"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true">${ICONS[name]||ICONS.pin}</svg>`;
const esc=(v)=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Fixed demonstration data. Hours and classifications are not a live campus service.
const PLACES=[
 {id:'hcafe',name:'H Café',sub:'Café · Campus dining',type:'Cafés',location:'P/F, Block FGHJ Courtyard',state:'closed',summary:'Opens today at 08:00',today:'08:00 – 22:00',tag:'Coffee & light meals',image:'food-thumb-hcafe.png',hours:[['Mon – Fri','08:00 – 22:00'],['Saturday','08:00 – 18:00'],['Sun / public holiday','10:00 – 18:00']]},
 {id:'soup',name:'VA210 Vending Machine',sub:'Chinese soup · Vending',type:'Vending',location:'P/F, Block VA',state:'open',summary:'Open 24 hours',today:'00:00 – 23:59',tag:'Chinese Soup',image:'food-thumb-soup.png',hours:[['Every day / public holiday','00:00 – 23:59']]},
 {id:'taobin',name:'VA210 Vending Machine',sub:'Drinks · Vending · Demo category',type:'Vending',location:'P/F, Block VA',state:'open',summary:'Open 24 hours',today:'00:00 – 23:59',tag:'Drinks',image:'food-thumb-taobin.png',hours:[['Every day / public holiday','00:00 – 23:59']]},
 {id:'communal',name:'Communal Student Restaurant',sub:'Restaurant · Chinese cuisine',type:'Restaurants',location:'4/F, Communal Building',state:'unknown',summary:'Check with the restaurant',today:'Hours unavailable',tag:'Chinese cuisine',image:'food-thumb-communal.png',hours:[]},
 {id:'gourmet',name:'Gourmet Shop',sub:'Take-away shop · Demo category',type:'Cafés',location:'P/F, Shaw Amenities Building',state:'unknown',summary:'Check with the restaurant',today:'Hours unavailable',tag:'Take-away',image:'food-thumb-gourmet.png',hours:[]}
];
const S={screen:'list',q:'',type:'All',open:false,view:'list',selected:'hcafe',expanded:[],scroll:0,history:[],dialog:false,scenario:'default'};
let page='prototype',figure=0,slideNo=0;
const params=new URLSearchParams(location.search);const capture=params.has('capture');
if(capture)document.body.classList.add('capture-mode');
const stateLabels={open:'Open now',closed:'Closed',unknown:'Hours unavailable'};
function statusHTML(p){return `<div class="status-row"><span class="status ${p.state}">${stateLabels[p.state]}</span>${p.state==='unknown'?'':`<span class="status-caption">${p.summary}</span>`}</div>`;}
function hoursHTML(p){return p.hours.length?`<div class="hours-table">${p.hours.map((h,i)=>`<div class="${i===0?'today':''}"><span>${h[0]}</span><span>${h[1]}</span></div>`).join('')}</div>`:`<p>Opening hours have not been provided for this demo record.</p>`;}
function cardHTML(p,staticMode=false){const expanded=S.expanded.includes(p.id);return `<article class="place-card" data-place="${p.id}"><div class="place-head"><img class="thumb" src="assets/${p.image}" alt="${esc(p.name)} logo"><button class="place-link" ${staticMode?'tabindex="-1"':`data-action="detail" data-id="${p.id}"`} aria-label="View details: ${esc(p.name)}, ${esc(p.sub)}"><span><strong>${p.name}</strong><small>${p.sub}</small></span><span class="chevron" aria-hidden="true">›</span></button></div><div class="place-location">${icon('pin')}<span>${p.location}</span></div>${statusHTML(p)}<div class="card-bottom"><button class="text-button" ${staticMode?'tabindex="-1"':`data-action="hours" data-id="${p.id}"`} aria-expanded="${expanded}" aria-controls="hours-${p.id}">Opening hours ${expanded?'⌃':'⌄'}</button><button class="text-button" ${staticMode?'tabindex="-1"':`data-action="detail" data-id="${p.id}"`}>View details ›</button></div><div id="hours-${p.id}" ${expanded?'':'hidden'}>${hoursHTML(p)}</div></article>`;}
function matches(){const q=S.q.toLowerCase().trim();return PLACES.filter(p=>(S.type==='All'||p.type===S.type)&&(!S.open||p.state==='open')&&(!q||[p.name,p.sub,p.location,p.tag].join(' ').toLowerCase().includes(q)));}
function appHeader(){return `<div class="app-header"><div class="app-header-top"><button class="text-button" data-action="home">‹ Home</button><span class="app-wordmark">PolyULife</span><span class="demo-tag">DEMO</span></div><div class="food-heading"><div><div class="food-kicker">CAMPUS DINING</div><h2>Find your<br>next bite <span>↗</span></h2></div><img class="food-art" src="assets/fresh-bowl.svg" alt=""></div></div>`;}
function toolbar(){return `<div class="toolbar"><div class="search-wrap">${icon('search')}<input id="place-search" type="search" placeholder="Search places or food" aria-label="Search places or food" value="${esc(S.q)}"><button class="clear-search" data-action="clear" aria-label="Clear search">×</button></div><div class="chips" role="group" aria-label="Place type">${['All','Restaurants','Cafés','Vending'].map(t=>`<button class="chip ${S.type===t?'active':''}" data-action="type" data-value="${t}" aria-pressed="${S.type===t}">${t}</button>`).join('')}</div><div class="list-controls"><label class="open-filter"><input id="open-filter" type="checkbox" ${S.open?'checked':''}>Open now</label><div class="view-switch" role="group" aria-label="Results view"><button data-action="view" data-value="list" class="${S.view==='list'?'active':''}" aria-pressed="${S.view==='list'}">List</button><button data-action="view" data-value="map" class="${S.view==='map'?'active':''}" aria-pressed="${S.view==='map'}">Map</button></div></div></div>`;}
function resultsHTML(){const ps=matches();return `<div class="result-heading" role="status"><span>${ps.length} ${ps.length===1?'place':'places'}${S.type!=='All'?` · ${S.type}`:''}${S.open?' · Open now':''}</span><span>Tue · 00:54 HKT</span></div>${ps.length?(S.view==='map'?mapHTML(ps):ps.map(p=>cardHTML(p)).join('')):`<div class="empty-state"><div class="empty-symbol">${icon('search')}</div><h3>No places found</h3><p>No results for ${S.q?`“${esc(S.q)}”`:'these filters'}.<br>Try another food or place name.</p><div class="button-row"><button class="primary-button" data-action="clear">Clear search</button><button class="secondary-button" data-action="reset-filters">Reset filters</button></div></div>`}`;}
function mapHTML(ps){return `<div class="map-figure"><img src="assets/food-map-full-campus.png" alt="Historical campus map from the original Food flow"><span class="map-legend">Illustrative pins · not to scale</span>${ps.map((p,i)=>`<button class="map-marker" style="left:${18+(i%3)*25}%;top:${15+Math.floor(i/3)*24}%" data-action="detail" data-id="${p.id}" aria-label="View map result: ${esc(p.name)}, ${esc(p.sub)}">${i+1}</button>`).join('')}</div><p style="font-size:11px;margin:0 17px 12px;color:var(--muted)">Map imagery: historical Google Maps capture. Pins illustrate selection only.</p>${ps.map(p=>cardHTML(p)).join('')}`;}
function backbar(title){return `<div class="backbar"><button data-action="back" aria-label="Back to previous screen">${icon('back')}Back</button><strong>${esc(title)}</strong></div>`;}
function detailHTML(){const p=PLACES.find(p=>p.id===S.selected);return `${backbar('Place details')}<div class="detail-hero"><span class="demo-tag">DEMO · TUE 00:54 HKT</span><br><img class="thumb" style="margin-top:16px" src="assets/${p.image}" alt="${esc(p.name)} logo"><h2>${p.name}</h2><p>${p.sub}</p>${statusHTML(p)}</div><section class="detail-section"><h3>Today’s opening hours</h3><div class="today-summary">${p.today}</div><p>Tuesday · Hong Kong time</p><details><summary>All opening hours</summary>${hoursHTML(p)}</details></section><section class="detail-section"><h3>Location</h3><p>${p.location}</p><button class="text-button" data-action="location">View location map ›</button><p class="map-caption">Map view uses historical imagery; no live location.</p></section><section class="detail-section"><h3>Food & drink</h3><button class="chip" data-action="tag" data-value="${esc(p.tag)}">${p.tag}</button></section>${p.id==='hcafe'?`<section class="detail-section"><h3>Other options</h3><button class="text-button" data-action="external">Online order ↗</button><p class="map-caption">Opens a service outside PolyULife.</p></section>`:''}`;}
function homeHTML(){return `<div class="app-header"><div class="app-header-top"><span class="app-wordmark">PolyULife</span><span class="demo-tag">DEMO HOME</span></div></div><div class="home-greeting"><div class="eyebrow">CAMPUS LIFE</div><img class="home-art" src="assets/fresh-cup.svg" alt=""><h2>A little break<br>between classes.</h2><p>Your next campus stop starts here.</p></div><div class="home-food"><h3>Food</h3><p>Campus dining, opening hours and locations.</p><button class="primary-button" data-action="food">Explore campus food ›</button></div><p style="padding:0 22px;font-size:12px">Home is a navigation placeholder. Other features belong to the corresponding team members.</p>`;}
function phoneHTML(){let html=S.screen==='home'?homeHTML():S.screen==='detail'?detailHTML():S.screen==='location'?`${backbar('Location')}<section class="detail-section"><h3>${esc(PLACES.find(p=>p.id===S.selected).name)}</h3><p>${esc(PLACES.find(p=>p.id===S.selected).location)}</p><img style="width:100%;border-radius:8px" src="assets/food-map-full-campus.png" alt="Historical campus map from the VA210 Food observation"><p class="map-caption">Historical VA210 map reference. This image is not a verified pin for every place. No live navigation or location tracking.</p></section>`:`${appHeader()}${toolbar()}<div id="food-results">${resultsHTML()}</div>`;return `<div class="device-status"><span>00:54</span><span>● ▰</span></div><div class="phone-app" id="phone-scroll" ${S.dialog?'inert aria-hidden="true"':' '}>${html}</div><div class="phone-homebar"></div>${S.dialog?`<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h3 id="dialog-title">Leave PolyULife?</h3><p>Online ordering is provided by an external service. This prototype demonstrates the handoff only.</p><div class="button-row"><button class="primary-button" data-action="close-dialog">Stay in PolyULife</button><button class="secondary-button" data-action="demo-external">Continue demo</button></div></section></div>`:''}`;}
const scenarios=[['default','默认列表','F01'],['hours','营业时间展开','F02'],['detail','餐饮点详情','F03'],['search','指定食品搜索','F04'],['empty','无结果恢复','F05'],['unknown','营业时间未知','F06'],['home','首页入口','F00']];
function intro(k,title,description){return `<div class="page-intro"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${description}</p></div><span class="subtle-label">FRESH CAMPUS / v0.2</span></div>`;}
function prototypePage(){return `${intro('01 / INTERACTIVE PROTOTYPE','吃什么，几点开门。','把餐饮点、营业时间和返回路径放在清晰的层级里。直接操作原型，或从右侧切换场景。')}<div class="preview-grid"><div class="stage"><div class="stage-label">FOOD · INTERACTIVE MOBILE PREVIEW</div><div class="phone" id="phone">${phoneHTML()}</div><p class="subtle-label" style="margin:16px 0 0">固定场景：周二 00:54（香港时间） · 演示数据</p></div><aside class="panel"><div class="section-label">PREVIEW SCENARIOS</div><div class="scenario-list">${scenarios.map(([id,label,n])=>`<button data-scenario="${id}" class="${S.scenario===id?'active':''}">${label}<span>${n} ↗</span></button>`).join('')}</div><div class="note-block"><h3>本轮改版重点</h3><ul><li>明确的详情入口</li><li>当天营业时间优先</li><li>搜索结果保留区分信息</li><li>返回后保留查询与位置</li></ul></div><div class="note-block"><h3>试走一遍</h3><p>搜索 Chinese Soup → 查看详情 → 查看位置 → 返回两次。查询条件会保留。</p></div><div class="note-block"><h3>证据边界</h3><p>营业时间使用历史样例与演示记录；分类与地图标记部分为设计示意。尚未进行真人 Maze 测试。</p></div><div class="flow-trail" id="flow-trail"></div></aside></div>`;}
const FIGURES=[{title:'营业时间与详情入口',before:'original-list.png',after:()=>cardHTML(PLACES[0],true)+cardHTML(PLACES[1],true),old:'Closed 旁使用泛化文案；省略号进入详情，含义需要用户理解。',new:'直接显示当天营业摘要，明确区分 Opening hours 与 View details。',source:'food-165444-list-scrolled-h-cafe.png'}, {title:'搜索结果中的区分信息',before:'original-search.png',after:()=>`<div class="toolbar"><div class="search-wrap">${icon('search')}<input value="Chinese Soup" readonly aria-label="Example search"></div></div><div class="result-heading">1 place · Chinese Soup</div>${cardHTML(PLACES[1],true)}`,old:'结果名称仍为 VA210 Vending Machine；食品标签与位置的识别效率需要验证。',new:'同一张卡片保留食品、楼层和营业状态，支持先识别再进入详情。',source:'food-160820-chinese-soup-tag-result.png'}];
function figureBoard(n){const f=FIGURES[n];return `<div class="figure-board"><div class="figure-header"><h2>${f.title}</h2><span class="figure-number">FIGURE ${String(n+1).padStart(2,'0')} / FOOD</span></div><div class="comparison"><div class="comparison-column"><h3>BEFORE · 原应用历史截图</h3><img class="original-shot" src="assets/${f.before}" alt="${f.title}原应用截图"><div class="comparison-caption annotation"><b>A</b><span>${f.old}</span></div></div><div class="comparison-column"><h3>AFTER · 提出的改版（DEMO）</h3><div class="new-shot">${f.after()}</div><div class="comparison-caption annotation"><b>B</b><span>${f.new}</span></div></div></div><div class="source-line">原图：12bitsD/comp3423-hci-project · ${f.source} · 香港时间 2026-09-29。改版为设计提案，未经过真人评估。</div></div>`;}
function figuresPage(){return `${intro('02 / REPORT FIGURES','让证据与设计对得上。','原应用与改版分栏，统一编号、说明和来源。可直接使用导出的 PNG，或在浏览器打印为 PDF。')}<div class="content-page"><div class="tab-strip">${FIGURES.map((f,i)=>`<button data-figure="${i}" class="${i===figure?'active':''}">图 ${i+1} · ${f.title}</button>`).join('')}</div>${figureBoard(figure)}<div class="download-row"><a href="exports/figure-0${figure+1}.png" download>下载当前插图 PNG ↓</a><span>排版源文件保留在本地页面中</span></div></div>`;}
const SLIDES=[
 {title:'Less searching.\nMore living.',sub:'PolyULife Food redesign\nFind a place. Check the hours.',kicker:'COMP3423 / VISUAL & UI DESIGN',cover:true},
 {title:'Food 的可用性问题',sub:'明确详情入口的含义；让当天营业时间更容易找到。\n这些是基于历史截图的设计假设，尚待真人验证。',kicker:'01 / OBSERVED INTERFACE',image:'assets/original-list.png'},
 {title:'营业时间优先',sub:'餐饮卡片直接显示当天状态，\n保留独立的营业时间与详情入口。',kicker:'02 / REDESIGN PROPOSAL',image:'exports/screen-list.png'},
 {title:'返回时保留上下文',sub:'从地图返回详情，再回到原来的搜索结果。\n搜索词、筛选与滚动位置随来源恢复。',kicker:'03 / INTERACTION',image:'exports/screen-detail.png'},
 {title:'共用一套视觉语言',sub:'米白画布、深蓝文字与明亮绿点缀。\n同一套颜色与排版规则贯穿界面、报告插图和演示文稿。',kicker:'04 / VISUAL SYSTEM',image:'exports/figure-02.png'},
 {title:'真人评估计划',sub:'让参与者查询营业时间、寻找指定食品，并返回继续比较。\n记录任务成功、答案正确性、错误点击与真实反馈。',kicker:'05 / EVALUATION PLAN',end:true}
];
window.STUDIO_SLIDES=SLIDES;
function slideHTML(n){return `<div class="slide-canvas rendered-slide"><img src="exports/slide-${n+1}.png" alt="${esc(SLIDES[n].title)} · slide ${n+1}"></div>`;}
function slidesPage(){return `${intro('03 / PRESENTATION','同一风格，换一个画幅。','6 页可编辑 PPT 样例：问题、改版、交互、视觉系统与评估计划。用于本地风格验收。')}<div class="content-page"><div class="slide-controls"><span class="slide-counter">${slideNo+1} / ${SLIDES.length}</span><div class="button-row"><button class="secondary-button" data-slide="prev" ${slideNo===0?'disabled':''}>← 上一页</button><button class="secondary-button" data-slide="next" ${slideNo===SLIDES.length-1?'disabled':''}>下一页 →</button></div></div>${slideHTML(slideNo)}<div class="download-row"><a href="exports/PolyULife-Food-Fresh-Campus-v02.pptx" download>下载可编辑 PPTX ↓</a><span>样例不包含编造的测试结果</span></div></div>`;}
function systemPage(){const cs=window.DESIGN_TOKENS.colors;return `${intro('04 / DESIGN SYSTEM','统一，来自可复用的规则。','颜色、字体、间距与交互状态使用同一组设计变量；界面与导出文件保持一致。')}<div class="content-page"><div class="system-grid"><section class="spec-section"><h2>01 · 色彩</h2>${[['accent','明亮绿 / 选中背景与重点'],['ink','主文字'],['muted','辅助文字'],['canvas','米白画布'],['success','营业中'],['warning','时间未知']].map(([key,label])=>`<div class="swatch-row"><span class="swatch" style="background:${cs[key]}"></span><div><strong>${label}</strong><small>${cs[key]}</small></div></div>`).join('')}<p>状态始终带文字说明，不仅依赖颜色。</p></section><section class="spec-section"><h2>02 · 文字层级</h2><div class="type-demo" style="font-size:32px;font-weight:bold">Campus food<small>页面标题 / 28–32 px</small></div><div class="type-demo" style="font-size:20px;font-weight:bold">H Café 营业时间<small>分节标题 / 20–24 px</small></div><div class="type-demo" style="font-size:16px">今天 08:00–22:00<small>正文 / 16 px；紧凑卡片 14–16 px</small></div><div class="type-demo" style="font-size:12px">P/F, Block FGHJ Courtyard<small>辅助说明 / 12 px 起</small></div><p>Arial / Microsoft YaHei；PPT 标题 32 pt 起，正文 20 pt，16:9 画幅。</p></section><section class="spec-section"><h2>03 · 间距与组件</h2><div class="spacing-demo">${[4,8,12,16,24,32,48].map(n=>`<div><i style="height:${n}px"></i>${n}</div>`).join('')}</div><div class="button-row"><button class="primary-button">主操作</button><button class="secondary-button">次操作</button></div><p style="margin-top:20px">卡片圆角 20 px，控件圆角 12 px；点击区域至少 44 × 44 px，键盘焦点外框 3 px。</p></section><section class="spec-section"><h2>04 · 状态与语气</h2>${['open','closed','unknown'].map((st)=>`<p><span class="status ${st}">${stateLabels[st]}</span></p>`).join('')}<p>明确区分“关闭”和“没有营业信息”。文案说明状态及可执行的下一步，不用模糊的 Further information。</p><a href="docs/STYLE-GUIDE.md">完整视觉规范 →</a></section></div></div>`;}
function handoffPage(){return `${intro('05 / HANDOFF','本地先验收，再进入协作。','保留原型源文件、规范、证据说明与 AGENTS.md。v0.2 已通过本地验收并获授权上传 GitHub。')}<div class="content-page"><div class="scope-note">本包用于 Food 与全组视觉方向的验收。浏览器原型不能替代课程要求的 Figma 原型；真人 Maze 评估仍需全组执行。</div><div class="doc-list">${[['README.md','使用说明','启动、场景与验收步骤'],['docs/STYLE-GUIDE.md','视觉与组件规范','页面、插图与 PPT 共用规则'],['AGENTS.md','Agent 工作约定','范围、证据、修改与上传规则'],['docs/FIGMA-HANDOFF.md','Figma 迁移说明','画框、组件、连线与返回规则'],['docs/EVIDENCE.md','数据与素材来源','真实观察、合成场景和设计假设'],['docs/ACCEPTANCE.md','本地验收清单','交互、视觉与边界'],['exports/PolyULife-Food-Fresh-Campus-v02.pptx','PPT 风格样例','6 页可编辑演示文稿']].map(([href,name,desc])=>`<a href="${href}" ${href.endsWith('pptx')?'download':''}><strong>${name}</strong><small>${desc} ↗</small></a>`).join('')}</div><div class="scope-note">v0.2 已通过本地验收并获授权上传；材料位于 prototypes/food-studio/，通过工作分支与 PR 供团队审阅。</div></div>`;}
function renderStudio(){document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page));const html=page==='figures'?figuresPage():page==='slides'?slidesPage():page==='system'?systemPage():page==='handoff'?handoffPage():prototypePage();document.getElementById('studio-content').innerHTML=html;bindSearch();}
function bindSearch(){const input=document.getElementById('place-search');if(input)input.addEventListener('input',()=>{S.q=input.value;S.scenario='custom';renderResults();});const check=document.getElementById('open-filter');if(check)check.addEventListener('change',()=>{S.open=check.checked;S.scenario='custom';renderResults();});}
function renderResults(){const root=document.getElementById('food-results');if(root)root.innerHTML=resultsHTML();}
function refreshPhone(){const el=document.getElementById('phone');if(!el)return;el.innerHTML=phoneHTML();bindSearch();const sc=document.getElementById('phone-scroll');if(sc&&S.screen==='list')sc.scrollTop=S.scroll;document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.toggle('active',b.dataset.scenario===S.scenario));}
function pushScreen(screen){const sc=document.getElementById('phone-scroll');S.history.push({screen:S.screen,q:S.q,type:S.type,open:S.open,view:S.view,selected:S.selected,expanded:[...S.expanded],scroll:sc?sc.scrollTop:0});S.screen=screen;S.scroll=0;S.dialog=false;refreshPhone();document.querySelector('#phone-scroll .backbar button')?.focus({preventScroll:true});}
function back(){const prev=S.history.pop();if(prev)Object.assign(S,prev);else S.screen='list';S.dialog=false;refreshPhone();}
function setScenario(id){Object.assign(S,{screen:'list',q:'',type:'All',open:false,view:'list',selected:'hcafe',expanded:[],scroll:0,history:[],dialog:false,scenario:id});if(id==='hours')S.expanded=['hcafe'];if(id==='detail'){S.history=[{screen:'list',q:'',type:'All',open:false,view:'list',selected:'hcafe',expanded:[],scroll:0}];S.screen='detail';}if(id==='search')S.q='Chinese Soup';if(id==='empty')S.q='Sushi';if(id==='unknown'){S.selected='communal';S.history=[{screen:'list',q:'',type:'All',open:false,view:'list',selected:'hcafe',expanded:[],scroll:0}];S.screen='detail';}if(id==='home')S.screen='home';refreshPhone();}
document.addEventListener('click',e=>{const scenario=e.target.closest('[data-scenario]');if(scenario){setScenario(scenario.dataset.scenario);return;}const f=e.target.closest('[data-figure]');if(f){figure=Number(f.dataset.figure);renderStudio();return;}const sl=e.target.closest('[data-slide]');if(sl){slideNo=Math.min(SLIDES.length-1,Math.max(0,slideNo+(sl.dataset.slide==='next'?1:-1)));renderStudio();return;}const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action;
 if(act==='detail'){pushScreen('detail');S.selected=b.dataset.id;refreshPhone();}
 if(act==='hours'){S.scroll=document.getElementById('phone-scroll').scrollTop;S.expanded=S.expanded.includes(b.dataset.id)?S.expanded.filter(id=>id!==b.dataset.id):[...S.expanded,b.dataset.id];refreshPhone();}
 if(act==='back')back();
 if(act==='home')pushScreen('home');
 if(act==='food')pushScreen('list');
 if(act==='location')pushScreen('location');
 if(act==='tag'){pushScreen('list');S.q=b.dataset.value;S.type='All';S.open=false;S.view='list';refreshPhone();}
 if(act==='clear'){S.q='';refreshPhone();document.getElementById('place-search')?.focus({preventScroll:true});}
 if(act==='reset-filters'){S.type='All';S.open=false;refreshPhone();}
 if(act==='type'){S.type=b.dataset.value;S.scroll=0;refreshPhone();}
 if(act==='view'){S.view=b.dataset.value;S.scroll=0;refreshPhone();}
 if(act==='external'){S.dialog=true;refreshPhone();document.querySelector('.dialog button')?.focus();}
 if(act==='close-dialog'||act==='demo-external'){S.dialog=false;refreshPhone();document.querySelector('[data-action="external"]')?.focus();}
});
document.addEventListener('keydown',e=>{if(S.dialog&&e.key==='Escape'){e.preventDefault();S.dialog=false;refreshPhone();document.querySelector('[data-action="external"]')?.focus();}else if(S.dialog&&e.key==='Tab'){const bs=[...document.querySelectorAll('.dialog button')];const last=bs.at(-1),first=bs[0];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'prototype';renderStudio();});
page=params.get('page')||location.hash.slice(1)||'prototype';figure=Number(params.get('figure')||0);slideNo=Number(params.get('slide')||0);renderStudio();if(params.has('state'))setScenario(params.get('state'));
